quests[1428] = { id = 1428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortwährende Gefahr", description = "Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.\n\nSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.", sourceObjective = "Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1429] = { id = 1429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verbannte der Atal'ai", description = "Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.\n\nDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.\n\nEr wurde ins Hinterland zu den Trollen der Bleichborken verbannt.\n\nIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist.", sourceObjective = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1430] = { id = 1430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frischfleisch", description = "Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.\n\nWenn Ihr vorhabt, zur Küste zu reisen, könnte es sich lohnen, wenn Ihr mir einige ihrer Beine bringt, damit ich sie nach Orgrimmar transportieren lassen kann.\n\nDie Küste liegt östlich von hier. Ihr solltet keine Probleme haben, die Kreaturen zu finden, die an den Stränden und im Meer umherhuschen.", sourceObjective = "Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[1431] = { id = 1431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Seid still, {name}, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.\n\nWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.\n\nWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.", sourceObjective = "Sprecht mit Keldran in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1432] = { id = 1432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Wenn die Allianz immer tiefer nach Kalimdor vorstößt, könnten falsche Schlussfolgerungen über mögliche Bündnisse der Horde mit der Brennenden Legion gezogen werden. Dazu darf es der Kriegshäuptling nicht kommen lassen. Und mit seinem Segen übernehme ich die Aufsicht darüber, dass alle Missverständnisse ausgeräumt werden.\n\nIch habe Agenten in der Gegend von Desolace am Geistwandlerposten nördlich des großen Kodofriedhofs. Wenn Ihr vom Verbrannten Tal im Steinkrallengebirge aus südwärts geht, solltet Ihr dort vorbeikommen. Wenn Ihr eintrefft, sucht Takata Stahlklinge auf.", sourceObjective = "Sprecht mit Takata Stahlklinge in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1433] = { id = 1433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Die Brennende Klinge verfolgt eigene Ziele; doch wisst, dass sie bis ins Mark böse sind und ihr Geist verderbt wurde. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten.\n\nKeldran schickte Maurin mit mir, weil er die Klinge und die Arglist ihrer Hexenmeister kennt.\n\nEr leitet unsere Verschwörungen gegen die Klinge, während ich mich um die anderen dämonischen Bedrohungen in Desolace kümmere.\n\nSprecht mit ihm und er wird Euch in seine Pläne einweihen.", sourceObjective = "Sprecht mit Maurin Knochenspalter in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1434] = { id = 1434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschmutzt durch Satyrn", description = "Eine Dämonenplage geschieht nicht ohne andere Einflüsse - etwas anderes ermöglicht dem Bösen, Fuß zu fassen.\n\nEs mag mit einem schwachen Geist beginnen, einer unnötigen Gier nach Macht, möglicherweise Rachedurst oder der Verlockung nach höchster Gerechtigkeit. Wenn der Schmerz uns übermannt, dann nutzt uns das Böse aus - das Böse wie die Satyrn.\n\nBande wurden zwischen ihnen und der Brennenden Klinge geknüpft und Thrall hätte sie getötet. Sucht sie nordöstlich von hier und kommt zu mir zurück, wenn Ihr sie zurückgeschlagen habt.", sourceObjective = "Besiegt 7 Schurken der Zornsäer, 7 Teufelsanbeter der Zornsäer, 7 Verräter der Zornsäer sowie 7 Höllenrufer der Zornsäer und kehrt zu Takata Stahlklinge in Desolace zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1435] = { id = 1435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Geist", description = "Für diese abscheulichen Kreaturen, die ihrem Lehen aus so egoistischen Gründen den Rücken kehren, ist der Tod höchst wünschenswert. Doch wenn man es mit denen zu tun hat, die sich der Dunkelheit verschrieben haben, reicht der Tod allein nicht aus.\n\nNehmt diesen Edelstein. Wenn einer der Brennenden Klinge dem Tode nahe ist, aktiviert seine Magie. Der Zauber wird den verderbten Geist aus seinem Opfer herausziehen und einen damit erfüllten Edelstein hinterlassen.\n\nBringt mir diese erfüllten Edelsteine, damit ich sie angemessen entsorgen kann.\n\nGeht jetzt, und möge Euch der Tod meiden.", sourceObjective = "Bringt den brennenden Edelstein und 15 erfüllte brennende Edelsteine nach Desolace zu Maurin Knochenspalter.", sourceObjectiveStatus = "unverified-source-field" }
quests[1436] = { id = 1436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Der Kampf läuft gut, {name}. Vielleicht lässt uns der Kriegshäuptling, bevor die Jahreszeiten wechseln, in unsere Heimat zurückkehren, wenn der Kampf gegen die Dämonen und ihre Unterlinge weiterhin so gute Fortschritte macht.\n\nKehrt zu Keldran zurück und lasst ihn wissen, was wir getan haben. Ich bin sicher, er belohnt Euch für Eure Taten hier. Seine Sache ist ihm wichtig und es wird ihn mit Stolz erfüllen, wenn er weiß, dass der Kriegshäuptling seine Sorgen respektiert.", sourceObjective = "Sprecht mit Keldran in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1437] = { id = 1437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Ich bin Vahlarriel, {name}. Ich kam her, um mich nach dem Befinden zweier vermisster Adliger einer Kaufmannsfamilie aus Darnassus zu erkundigen - Haus Malem. Der Vater des Hauses fürchtet das Schlimmste. Ich soll tun, was ich kann, um seine vermissten Kinder zu finden. Ich habe noch nicht mit der Suche nach Tyranis und Dalinda begonnen, hoffe aber, ich werde mich nicht lange hier aufhalten.\n\nZuletzt hörte man, dass sie vor wenigen Wochen durch das Steinkrallengebirge gekommen sein sollen.\n\nFalls Ihr ihren Wagen findet, sucht mich bitte unverzüglich auf.", sourceObjective = "Sucht und findet den Wagen von Tyranis und Dalinda Malem in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1438] = { id = 1438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Sucht Dalinda und Tyranis, wenn Ihr könnt, und berichtet mir von Euren Funden. Beginnt Eure Suche in dieser Festung. Ich setze mich sofort mit meinen Vorgesetzten in Darnassus in Verbindung und informiere sie über die Situation.\n\n{name}, ich möchte Euch noch etwas wissen lassen. Meine Vorgesetzten haben Besorgnis wegen Tyranis und seinen Motiven für diese Reise geäußert. Es ist ihnen wichtiger, dass Dalinda gefunden und wohlbehalten zurückgebracht wird. Tyranis soll... überprüft werden, ehe man ihn nach Hause bringt.", sourceObjective = "Sucht Dalinda Malem in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1439] = { id = 1439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Tyranis", description = "Wir wurden hierher gebracht, nachdem die Orcs alle unsere Wachen und Diener abgeschlachtet hatten. Oh, was haben sie ihnen Schreckliches angetan! Ich dachte, sie würden uns auf der Stelle töten, doch dann wurde deutlich, dass sie andere Pläne hatten.\n\nTyranis versuchte, mit ihnen zu reden. Ich glaube, er wollte sie mit seinem arkanen Wissen beeindrucken...Ich bin nicht sicher, warum.\n\nBitte, ich kann hier nicht weg, bevor ich weiß, was meinem Bruder zugestoßen ist. Sucht ihn und kommt zu mir, wenn Ihr sein Schicksal kennt.", sourceObjective = "Sucht Tyranis Malem in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1440] = { id = 1440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Vahlarriel", description = "Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt. Wenn Ihr bereit seid, hier hält mich nichts mehr - wir können aufbrechen, falls es Euch passend erscheint.", sourceObjective = "Begleitet Dalinda Malem aus der Festung Donneraxt und kehrt zu Vahlarriel Dämonenjäger nach Desolace zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1442] = { id = 1442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Koredelstein", description = "Seid gegrüßt, {name}. Was kann ich für einen tun, der dem heiligen Weg folgt?\n\nAh ja, Stillbrunn, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.\n\nEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Koredelstein edle Motive hat.\n\nWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten des Eschentals. Dort findet Ihr die Tiefschwarze Grotte mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, {class}.", sourceObjective = "Bringt einen Koredelstein zu Thundris Windwirker an der Dunkelküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[1444] = { id = 1444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Fel'Zerul", description = "Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.\n\nSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.\n\nAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.\n\nDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr...", sourceObjective = "Kehrt zu Fel'Zerul in Steinard zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1445] = { id = 1445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Atal'Hakkar", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", sourceObjective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Steinard.", sourceObjectiveStatus = "unverified-source-field" }
quests[1446] = { id = 1446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an der Prophet", description = "Meine Bleichborkenbegleiter mögen keine Fremden in ihrer Nähe.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", sourceObjective = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an.", sourceObjectiveStatus = "unverified-source-field" }
quests[1447] = { id = 1447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Hm, Ihr seid offenkundig nicht <einer/eine> der Klügsten Eures Handwerks, <der/die> je nach Sturmwind kam, aber <einer/eine> der Dümmsten, wenn Ihr nicht wieder fortgeht.\n\nHabt Ihr meine Freunde getroffen?", sourceObjective = "Besiegt Dashel Steinfaust in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1448] = { id = 1448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Tempel", description = "Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, {class}.\n\nDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!\n\nAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.\n\nMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.\n\nHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.", sourceObjective = "Brohann Fassbauch in Sturmwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1449] = { id = 1449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Hinterland", description = "Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.\n\nIch reiste zu dem berühmten Greifenhorst beim Nistgipfel im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf...\n\nDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.\n\nBegebt Euch dorthin und sucht nach Falstad Wildhammer.\n\nWir müssen herausfinden, was dem Piloten zugestoßen ist.", sourceObjective = "Sprecht mit dem obersten Than, Falstad Wildhammer, am Nistgipfel im Hinterland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1450] = { id = 1450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifenmeister Krallenaxt", description = "Ihr seid also nur ein <besserer Botenjunge/besseres Botenmädchen> für einen alten Tattergreis der Forscherliga, hm?\n\nHört mir gut zu, {class}. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Krallenaxt aus? Ja?\n\nWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.\n\nUnd jetzt trollt Euch.", sourceObjective = "Sprecht mit Greifenmeister Krallenaxt im Horst beim Nistgipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1451] = { id = 1451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodie Kniegräber", description = "Rhapsodie fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.\n\nAber der alte Kniegräber brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsodie.\n\nDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.\n\nZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet...", sourceObjective = "Sucht Rhapsodie Kniegräber im Hinterland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1452] = { id = 1452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodies Kalimdor-Cocktail", description = "Hicks!\n\nDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!\n\nWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!\n\nIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.\n\nMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...\n\nEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!", sourceObjective = "Rhapsodie Kniegräber im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoclebern und 3 Eisenfelllebern bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1453] = { id = 1453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschäfte der Wiederholer in Desolace", description = "Es gibt Arbeit in Desolace, {name}. Das ist ein grässlicher Ort, beschmutzt von Zentauren und anderer Unbill. Aber wenn Ihr eine Woche ehrlicher Arbeit sucht, dann geht dorthin, besucht Kreldig Ungor und sagt ihm, ich hab Euch geschickt.\n\nIhr findet ihn an der Nijelspitze - dem gemütlichen kleinen Lager in den Bergen des nördlichen Desolace. Haltet Euch einfach ostwärts, wenn Ihr vom Steinkrallengebirge kommt. Man übersieht es leicht, also seid wachsam.", sourceObjective = "Sprecht mit Kreldig Ungor in Desolace.", completion = "Schön zu sehen, dass die Wiederbeschaffer nicht knapp an Arbeit oder Abenteurern sind, die ihnen aushelfen wollen.\n\nIch bin Kreldig, {name}. Es war eine kluge Entscheidung, den Wiederbeschaffern zu helfen. Heutzutage braucht jeder irgendetwas: Die Leute verlieren ein Familienerbstück, einen magischen Gegenstand oder einen geliebten Menschen. Es ist schon recht erstaunlich. Aber wenn die Wiederbeschaffer in der Gegend sind, gibt es keinen Grund, warum nicht jeder für einen angemessenen Preis wiederbekommen sollte, was er verloren hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1454] = { id = 1454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Nehmt doch Platz...\n\nMein erster Auftrag betrifft den Magier Karnitol - eine Art Edelmann in Sturmwind. Offenbar wurde sein Schiff vor der nordwestlichen Küste von Desolace von Meeresriesen angegriffen. Er und seine Gefolgsleute versuchten, eine seiner wertvolleren Truhen an Land zu bringen, aber als die Meeresriesen in Schwärmen angriffen, beschloss er, sie aufzugeben und sich und seine Gefolgsleute in Sicherheit zu teleportieren.\n\nEr möchte, dass wir die Truhe samt ihrem Inhalt finden und zu ihm nach Sturmwind bringen.", sourceObjective = "Sucht Karnitols Truhe in Desolace.", completion = "Ihr bemerkt, dass die Truhe keine Wasserschäden genommen hat.\n\nAls Zweites bemerkt Ihr, dass der Deckel aufgebrochen wurde. Eventuelle magische Fallen, die der Sicherung dienten, wurden längst ausgelöst - das erkennt man an den Brandspuren an den Kanten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1455] = { id = 1455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.\n\nIhr werft einen Blick in die Truhe und stellt fest, dass sie leer ist.\n\nDa Ihr nicht wisst, was Ihr sonst tun sollt, klappt Ihr die Truhe zu und rüstet zum Aufbruch. Kreldig wird enttäuscht sein.", sourceObjective = "Kehrt zu Kreldig Ungor in Desolace zurück.", completion = "Willkommen in der Nijelspitze, {name}. Sagt mir, was Ihr gefunden habt.\n\nWas!? Nichts? Ich fürchte, eine leere Truhe bringt uns keinen Lohn ein.\n\nErzählt mir mehr von diesen Spuren, die Ihr gesehen habt... diesen Schlitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1456] = { id = 1456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Faszinierend.\n\nVielleicht besteht ja doch noch Hoffnung.\n\nAn derselben Küste, aber viel weiter nördlich, nahe der Insel Ranazjar, liegen Ruinen der Nachtelfen auf dem Grund des Meeres. Ein Stamm von Naga, die Zackenkämme, sind dort zu Hause. Das dürfte unsere beste Chance sein.\n\nWenn ein Kundschaftertrupp sich so weit in den Süden wagte, müssen sie sehr mächtig sein. Wenn Ihr Kanitols Habseligkeiten finden wollt, würde ich mit den mächtigeren Naga anfangen: den Gezeitenjägern oder den Meerhexen.", sourceObjective = "Sucht Karnitols Ranzen und bringt ihn zu Kreldig Ungor in Desolace zurück.", progress = "Nicht, dass ich Nijel zu nahe treten wollte, wer immer das sein mag, aber dieses Lager ist nicht das bequemste, das ich je gesehen habe. Wenn Ihr wisst, was ich meine, {name}.", completion = "Das ist toll, {name}! Ihr habt Karnitols Habseligkeiten gefunden!\n\nDiese elenden Naga machen ständig Ärger. Ich würde lieber mein Leben lang Krieg gegen die Horde führen als gegen ihre Art anzutreten.\n\nIhr habt den Wiederholern einen großen Dienst erwiesen. Bitte nehmt dies mit unserem Dank an!", sourceObjectiveStatus = "unverified-source-field" }
quests[1457] = { id = 1457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Bringt Karnitols Sachen zu Roetten in Eisenschmiede, er wird Euch die gute Arbeit wohl vergelten.\n\nHaha, wenn Ihr nicht aufpasst, wird er so zufrieden sein, dass er Euch bittet, als Festangestellter bei uns zu bleiben.\n\nWieder einmal gut gemacht, {name}.\n\nSeid auf dem Rückweg vorsichtig und lasst Euch nicht zu viel Zeit - Karnitol ist nicht der Geduldigste, aber dennoch höchst großzügig.", sourceObjective = "Bringt Karnitols Ranzen zu Roetten Steinhammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1458] = { id = 1458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Zu meinen Pflichten hier gehört, Reagenzien für Linkstatsch zu beschaffen, einen Gnomenmagier in Kharanos. Roetten glaubt, das sei ein Kinderspiel, da wir ohnehin schon hier draußen sind. Ihm ist es gleich, dass wir auch so schon unterbesetzt sind.\n\nDie ersten paar Gegenstände auf seiner Liste sollten leicht zu beschaffen sein, und für alle, die mir helfen, springt eine satte Belohnung raus.\n\nIch brauche einige Hörner und Klauen von den Satyrn der Zornsäer östlich von hier. Bringt sie mir, dann nehmen wir uns den Rest der Liste vor.", sourceObjective = "Bringt 10 Zornsäerklauen und 10 Zornsäerhörner zu Kreldig Ungor in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1459] = { id = 1459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Als Nächstes steht auf Linkstatschs Liste... mal sehen... hmm. Oh, da haben wir es.\n\nRecht einfach, aber mit sehr expliziten Anweisungen. Er braucht Gift von den Skorpashi und Bälge von Kodos. Im Kleingedruckten steht, beide müssen von bestimmten Kreaturen sein: Das Gift soll von irgendeinem Skorpashi stammen und der Balg muss von einem gealterten Kodo sein, aber keinem sterbenden oder uralten.\n\nMagier, ich sage Euch, was die so alles wollen... abartig.", sourceObjective = "Bringt 7 Phiolen Skorpashigift und 3 Bälge von gealterten Kodos zu Kreldig Ungor in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1462] = { id = 1462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdsapta", sourceObjective = "Sprecht mit Seherin Rabenfeder wegen eines weiteren Erdsaptas.", sourceObjectiveStatus = "unverified-source-field" }
quests[1463] = { id = 1463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdsapta", sourceObjective = "Sprecht mit Canaga Erdenrufer wegen eines weiteren Erdsaptas.", sourceObjectiveStatus = "unverified-source-field" }
quests[1464] = { id = 1464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersapta", sourceObjective = "Sprecht mit Telf Joolam wegen eines weiteren Feuersaptas.", sourceObjectiveStatus = "unverified-source-field" }
quests[1465] = { id = 1465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Als Ihr Eure Suche nach dem Wagen fortsetzt, findet Ihr nicht nur einen Anhänger, sondern auch Fußspuren, die in Richtung Süden führen. In der Ferne seht Ihr Rauch von einem großen Fort aufsteigen. Der Rauch stammt von einem Lagerfeuer, nicht von brennenden Gebäuden. Euer Instinkt sagt Euch, dass die Malems, wenn sie noch leben, in diese Richtung gebracht wurden.\n\nIhr seid der Ansicht, dass Vahlarriel an der Nijelspitze nicht nur den Anhänger sehen sollte, den Ihr gefunden habt, sondern auch von den Lebenszeichen im Süden wissen sollte.", sourceObjective = "Kehrt mit Malems Anhänger zu Vahlarriel Dämonenjäger in Desolace zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1466] = { id = 1466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Das ist der letzte Gegenstand und ganz ehrlich, er ist nicht schön. Ich gehe auch davon aus, dass Ihr dafür etwas länger braucht als für die anderen Gegenstände.\n\nDoch genug der Warnungen, fangen wir an. Linkstatsch sagt, er braucht Folgendes: zehn Gehirne, entweder von Manafressern, Magierjägern oder Leyjägern, zehn Netherflügel von einer Nethermaid, -schwester oder -zauberin. Und... zehn Phiolen Verdammniswächterblut von einem Hauptmann oder Lord der Verdammniswächter.\n\nGanz einfach, hm? Tja... ich hätte Verständnis dafür, wenn Ihr dies ausschlagen wollt.", sourceObjective = "Bringt 10 Teufelshundgehirne, 10 Netherflügel und 10 Phiolen Verdammniswächterblut zu Kreldig Ungor in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1467] = { id = 1467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Eisenschmiede zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Linkstatschs Päckchen vom Hals hat. Gebt ihm das, es müsste genügen, damit Ihr Euren Anteil bekommt.\n\nKeine Bange, ich werde trotzdem ein gutes Wort für Euch einlegen, wenn ich zurück bin. Ich sollte nicht mehr lange in Desolace bleiben müssen.", sourceObjective = "Bringt Linkstatschs Päckchen zu Roetten Steinhammer in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1468] = { id = 1468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, <Freund/Freundin>. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann nur kurze Zeit verwendet werden, normalerweise nur in der Kinderwoche selbst. Durch Benutzung der Pfeife könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nWorauf wartet Ihr noch, {name}, benutzt die Pfeife und trefft Euren Schützling. Das Kind freut sich bestimmt schon darauf, Euch kennenzulernen.", sourceObjective = "Benutzt die Pfeife des Menschenwaisenkindes, um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Um... hi. Meine Name ist Randis und ich glaube, Ihr sucht nach mir? Ihr seid ein Abenteurer, genauso wie es meine Mama und mein Papa waren. Ich bin so glücklich Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[1469] = { id = 1469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodies Geschichte", description = "Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!\n\nUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!\n\nJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!", sourceObjective = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Fassbauch in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1470] = { id = 1470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing the Veil", description = "Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.\n\nAnd you will learn.\n\nThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.\n\nI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.Ihr erlernt:" }
quests[1471] = { id = 1471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.\n\nMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.\n\nWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.Ihr erlernt:", sourceObjective = "Beschwört mithilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halger im Magieviertel von Unterstadt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1472] = { id = 1472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Ein Sukkubus ist ein Verschlinger von Seelen, Zerstörer von Herzen, Versucher der Menschen. Eine durch und durch böse und engstirnige Kreatur.\n\nOhne Anreiz kann er nicht in unsere Welt gebracht werden.\n\nDoch wir wenden seine eigene Kraft gegen ihn an. Den Herzen guter, reiner oder liebender Männer kann der Sukkubus nicht widerstehen und tritt in unsere Welt herüber. Dann könnt Ihr ihn beherrschen und zu Eurem Eigen machen.\n\nSprecht mit meinem Assistenten Godrick Farsan im Tempel. Er hilft Euch bei der Suche nach einem Köder.", sourceObjective = "Sprecht mit Godrick Farsan im Tempel der Verdammten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1473] = { id = 1473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreatur der Leere", description = "Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.\n\nEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.\n\nEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.\n\nLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.", sourceObjective = "Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1474] = { id = 1474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Benutzt diese Herzen und wirkt einen Zauber am Beschwörungskreis, um eine Tür zu öffnen, durch die der Sukkubus kommen kann. Eure Mächte sind jetzt größer und Ihr werdet sie alle brauchen, um den Sukkubus zu besiegen. \n\nHütet Euch vor seinen Bezauberungen, {name}, manch starker Geist wurde schon seinem Willen unterworfen. Wenn er überwunden wurde, kehrt der Sukkubus in die Leere zurück, dann lehre ich Euch den Zauber, um ihn nach Eurem Gutdünken zurückzurufen.Ihr erlernt:", sourceObjective = "Beschwört mithilfe der reinen Herzen einen Sukkubus, unterwerft ihn und bringt die reinen Herzen dann zu Carendin Halger im Magieviertel von Unterstadt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1475] = { id = 1475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tempel von Atal'Hakkar", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, {name}.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.", sourceObjective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Fassbauch in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1476] = { id = 1476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen der Reinen", description = "Männer mit Ehre und Güte? Existiert so ein Mann?\n\nViele Recherchen waren erforderlich, doch durch Geschichten, die ich hörte, konnte ich zwei Männer finden, die genügen sollten.\n\nDer Erste ist Dalin Schmiedevater, der sich der Fürsorge für die Flüchtlinge von Lordaeron verschrieben hat, die von ihresgleichen am Graumähnenwall verstoßen werden.\n\nDer andere ist Comar Villard, ein Mann, der seiner verlorenen Liebsten treu blieb und im Sumpfland nach Spuren seiner Frau sucht.\n\nBringt ihre Herzen zu Carendin. Doch zuvor möchte ich Euch Eure Opfer zeigen.", sourceObjective = "Bringt die Herzen von Dalin Schmiedevater und Comar Villard zu Carendin Halgar im Tempel der Verdammten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1477] = { id = 1477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überaus wichtige Vorräte", description = "Unsere Magier führen Forschungen in der Burg Nethergarde in den Verwüsteten Landen durch, die entscheidend für unser Verständnis der Dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch unsere Nachschubwege nach Nethergarde sind dürftig.\n\nIhr müsst helfen sicherzustellen, dass der Nachschub nach Nethergarde gelangt. Meldet Euch bei Wachhauptmann Sorigal in Dunkelhain und tut, was er verlangt. Diese Aufgabe führt Euch in Feindesland, {name}. Macht Euch bereit.", sourceObjective = "Sprecht mit Wachhauptmann Sorigal in Dunkelhain im Dämmerwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[1478] = { id = 1478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halgar's Summons" }
quests[1479] = { id = 1479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Baum der Ewigen", description = "Ich habe Geschichten von den Nachtelfen gehört, darüber, dass sie ihre Bank in einen Baum gebaut haben, der aber wie ein Bär aussieht. Das ist so cool! Nachtelfen sind niedlich, wie sie die Natur lieben und so, aber Bären sind der Hammer!\n\nWürdet Ihr bitte mit mir den Bärenbaum in Darnassus angucken gehen? Es gibt ein Boot, das uns ganz in die Nähe dorthin bringt und es wird auch bestimmt nicht lange dauern. Bitte, bitte, bitte!", sourceObjective = "Begleitet Euren Schützling zur Bank in Darnassus. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1480] = { id = 1480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corrupter" }
quests[1481] = { id = 1481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Ich denke, mit den entsprechenden Reagenzien kann ich diesen Dämonenlord finden.\n\nWenn er wirklich so mächtig ist, wie ich vermute, brauche ich gesammelte Gegenstände von tödlichen Kreaturen. Doch Ihr handelt im Namen des Kriegshäuptlings, daher werdet Ihr die Aufgabe gewiss übernehmen.\n\nAls Erstes muss ich jeden Schutzzauber brechen, den er gegen Wahrsagen hat. Daher brauche ich den Skalp eines Satyrs... aber nicht den eines beliebigen Satyrs. Der Skalp muss von einem Schattenpirscher der Zornsäer stammen.\n\nSucht in den antiken Ruinen nordöstlich von Desolace nach ihnen.", sourceObjective = "Bringt Maurin Knochenspalter in Desolace einen Schattenpirscherskalp.", sourceObjectiveStatus = "unverified-source-field" }
quests[1482] = { id = 1482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Ein Orakelkristall wäre genau richtig. Die Naga stellen sie her, damit ihre Orakel sie benutzen können.\n\nNordwestlich von hier liegt ein großes Korallenriff vor der Küste, das die Naga als ihre Heimat nutzen, da es so nahe am Ufer liegt. Dort könnt Ihr ihre Orakel finden. Die Zackenkammnaga sind tödlich und reagieren ungnädig auf Euer Eindringen, seid daher vorsichtig und eilt Euch.\n\nWenn Ihr zurückkehrt, suchen wir diesen Dämonenlord Azrethoc.", sourceObjective = "Bringt Maurin Knochenspalter in Desolace einen Orakelkristall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1483] = { id = 1483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziz Fizziks", description = "Die Venture Company stahl viele meiner besten Goblindenker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.\n\nVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Pfeifzang ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.\n\nVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.", sourceObjective = "Sprecht mit Ziz Fizziks bei der Scherwindklippe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1484] = { id = 1484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Diese Kreatur ist weitaus gefährlicher als ich dachte. Zweifellos stellt Takata in Frage, dass ich so einer Kreatur gewachsen bin, und es würde ihn in seiner Ehre kränken, wenn er nicht wüsste, was gerade passierte.\n\nSprecht mit dem Schwertkämpfer, sagt ihm, Ihr seid bereit, den Dämon zu erschlagen, wenn er es erlaubt, aber bedrängt ihn nicht zu sehr. Es ist besser, wenn er denkt, dass es seine Idee war.", sourceObjective = "Sprecht mit Takata Stahlklinge in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1485] = { id = 1485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.\n\nDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.\n\nBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der schändlichen Familiare aus der Höhle im Nordosten.Ihr erlernt:", sourceObjective = "Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[1486] = { id = 1486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviatbälge", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab und holt einige Deviatbälge.", sourceObjective = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[1487] = { id = 1487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung der Deviat", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.\n\nNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.\n\nWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.\n\nWagt Euch in die Höhlen, {name}, und löscht die Deviatbrut aus.", sourceObjective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1488] = { id = 1488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden. Besonders wenn er versucht, Einfluss über die Brennende Klinge zu bekommen, um seine Ziele voranzutreiben.\n\nIhr habt schon gezeigt, dass Ihr den Kriegshäuptling unterstützen möchtet. Ich verlasse mich darauf, dass Ihr eine Truppe zusammenstellt, die den Dämonenlord und seinen Hexenmeisterdiener besiegt.\n\nWenn Ihr bereit seid, geht direkt nach Süden und kehrt zu mir zurück, wenn die Bedrohung beseitigt wurde.", sourceObjective = "Besiegt Lord Azrethoc und Jugkar Grimm'rod. Kehrt dann zu Takata Stahlklinge in Desolace zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1489] = { id = 1489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hamuul Runentotem", description = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.\n\nDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runentotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.\n\nIhr findet ihn in Donnerfels auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Hamuul Runentotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[1490] = { id = 1490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nara Wildmähne", description = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.\n\nIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.\n\nSprecht mit Nara. Sie ist in diesem Zelt da drüben.", sourceObjective = "Sprecht mit Nara Wildmähne.", sourceObjectiveStatus = "unverified-source-field" }
quests[1491] = { id = 1491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klugheitstränke", description = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!\n\nEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!\n\nIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", sourceObjective = "Sammelt 6 Portionen Klageessenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1492] = { id = 1492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftmeister Flunkerblick", description = "Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratschet zu bringen, und die letzte Karawane ist schon aufgebrochen.\n\nKönntet Ihr sie bitte freundlichst zu Werftmeister Flunkerblick bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.", sourceObjective = "Bringt die gesicherte Kiste zu Werftmeister Flunkerblick in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1498] = { id = 1498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Verteidigung", description = "Als Krieger ist eine unserer wichtigsten Aufgaben... der Schutz. Wir sind der Schild der Horde und sorgen für die Sicherheit unserer schwächeren Brüder. Wenn Ihr Euch bei uns einreihen möchtet, müsst Ihr mir Eure Tauglichkeit beweisen.\n\nGeht zum Donnergrat in Durotar, wo die Blitzechsen und Donnerechsen hausen. Jagt die Bestien! Zeigt mir, dass Ihr härter als sie seid! Trotzt ihren Angriffen und bringt mir einen Stapel ihrer versengten Schuppen als Beweis.\n\nGelingt Euch das, unterrichte ich Euch.", sourceObjective = "Bringt 5 versengte Schuppen zu Uzzek bei der Fernwacht im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1499] = { id = 1499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die schändlichen Familiare gekämpft habt.\n\nIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.", sourceObjective = "Sprecht mit Zureetha Fernblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[1500] = { id = 1500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung von Naralex" }
quests[1501] = { id = 1501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreatur der Leere", description = "So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.\n\nEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.\n\nAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Brennenden Klinge gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.", sourceObjective = "Holt die Schrifttafel der Verga für Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1502] = { id = 1502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thun'grim Brandblick", description = "Es ist wichtig, dass ein Krieger eine hochwertige Waffe hat. Und wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist das Thun'grim Brandblick. Er ist ein Einsiedler, der auf den Hügeln östlich des Wegekreuzes haust.\n\nWenn Ihr eine Waffe sucht, Krieger, dann solltet Ihr Euch an Thun'grim wenden. Um ihn zu finden reist Ihr zuerst zum Wegekreuz im Westen und wendet Euch dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel.", sourceObjective = "Sprecht mit Thun'grim Brandblick im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1503] = { id = 1503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmiedeter Stahl", description = "Ich gebe Euch eine Waffe, {name}, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Klingenmähnen von Nordwesten in mein Lager. Sie wollten nicht mit mir kämpfen, wissen aber, wie schlecht es um mein Augenlicht bestellt ist. Einige lenkten mich durch Schnauben ab, während die anderen mich bestahlen. Diese Feiglinge!\n\nSie nahmen eine Eisentruhe mit, in der sich Schmiedestahlbarren befanden. Wenn Ihr sie wiederbeschaffen könnt, bekommt Ihr die Waffe, die Ihr sucht.\n\nSucht im Stacheleberlager nach der Eisentruhe und bringt die Schmiedestahlbarren zurück.", sourceObjective = "Bringt die Schmiedestahlbarren zu Thun'grim Brandblick im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1504] = { id = 1504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Feuerklinges Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.\n\nIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.Ihr erlernt:", sourceObjective = "Beschwört mithilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Blutauge in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1505] = { id = 1505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Uzzek", description = "Die Horde ehrt ihre Krieger, da ihre Kraft außer Frage steht. Doch die wahrhaft großen Helden sind auch große Schüler.\n\nSucht nach Uzzek. Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst. Ihr findet ihn südlich der Fernwacht, der Orcgarnison an der Grenze von Brachland und Durotar.", sourceObjective = "Sprecht mit Uzzek bei der Fernwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1506] = { id = 1506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'ruls Beschwörung", description = "Ihr da. {name}, richtig?\n\nIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.\n\nMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.", sourceObjective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1507] = { id = 1507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sukkubus zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.\n\nEin Sukkubus kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.\n\nEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.", sourceObjective = "Sprecht mit Cazul in der Kluft der Schatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1508] = { id = 1508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blinde Cazul", description = "Hmmm... Aber natürlich seid Ihr nicht gekommen, um deshalb mit mir zu sprechen.\n\nWenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.\n\nHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, {name}, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.\n\nGeht zu ihr.", sourceObjective = "Sprecht mit Zankaja in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1509] = { id = 1509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von Dogran", description = "Dogran, mein Gefährte, wurde jüngst zum Dienst am Wegekreuz abkommandiert. Es war eine Beförderung und er war sehr stolz.\n\nIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.\n\nSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...\n\nVielleicht könntet Ihr zum Wegekreuz gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.", sourceObjective = "Sprecht mit Gazrog beim Wegekreuz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1510] = { id = 1510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von Dogran", description = "Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.\n\nSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.", sourceObjective = "Sprecht mit Ken'zigla am Malaka'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[1511] = { id = 1511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken'ziglas Trunk", description = "Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.\n\nDa habt Ihr ihn, {name}. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.\n\nWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.", sourceObjective = "Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo.", sourceObjectiveStatus = "unverified-source-field" }
quests[1512] = { id = 1512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebesgabe", description = "Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.\n\nLasst mich allein, {name}. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.\n\nUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.", sourceObjective = "Bringt den schmutzverkrusteten Anhänger zu Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1513] = { id = 1513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Bringt dies zum Beschwörungskreis in Neerus Zelt, {name}. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.\n\nWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.Ihr erlernt:", sourceObjective = "Beschwört mithilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Blutauge in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1514] = { id = 1514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte" }
quests[1515] = { id = 1515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dograns Gefangenschaft", description = "Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.\n\nDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.\n\nViel Glück.", sourceObjective = "Bringt Ken'ziglas Trunk zu Dogran im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1516] = { id = 1516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, <junger/junge:c> {class}. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.\n\nDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.\n\nSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.", sourceObjective = "Bringt 2 Teufelspirscherhufe zu Canaga Erdenrufer im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1517] = { id = 1517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.\n\nDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo... vergesst das nicht.\n\nBesucht den Geisterfelsen südwestlich von hier... er befindet sich am Ende des Verborgenen Pfades. Trinkt Euer Sapta dort und... tja, Ihr werdet schon sehen.", sourceObjective = "Sucht den Geisterfelsen und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1518] = { id = 1518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Erdenrufer. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.\n\nHabt Geduld, {name}. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", sourceObjective = "Bringt den Rohquarz zu Canaga Erdenrufer im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1519] = { id = 1519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, {class}. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.\n\nDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.\n\nSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.", sourceObjective = "Bringt 2 Dosen Ritualsalbe zu Seherin Rabenfeder im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[1520] = { id = 1520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.\n\nDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.\n\nSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.", sourceObjective = "Sucht den Kodofels und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1521] = { id = 1521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Seherin Rabenfeder. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.\n\nHabt Geduld, {name}. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", sourceObjective = "Bringt den Rohquarz zu Seherin Rabenfeder im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[1522] = { id = 1522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Feuer sei mit Euch, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen der Erde und scheint mir bereit, mit Kranal zu sprechen.\n\nKranal lebt nördlich des Wegekreuzes im Brachland. Er kennt sich mit den Elementen aus und kann Euch was übers Feuer beibringen...wenn Ihr denkt, dass Ihr bereit seid.\n\nEr ist leicht zu finden, geht nur nicht zu weit. Wenn Ihr zu weit geht, seid Ihr plötzlich im Elfenland.", sourceObjective = "Sucht Kranal Fiss im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1523] = { id = 1523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich des Wegekreuzes, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1524] = { id = 1524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.\n\nAm Südstromfluss in Durotar, vor dem Großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht... den Schrein der Schlafenden Flamme.\n\nBringt ihm diese Fackel... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.", sourceObjective = "Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1525] = { id = 1525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.\n\nZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.\n\nIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Klingenmähnen im östlichen Brachland mit sich führen.\n\nDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Brennenden Klinge. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.", sourceObjective = "Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1526] = { id = 1526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.\n\nSchlagt ihn schnellstens nieder, {name}, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.", sourceObjective = "Besiegt die geringe Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", sourceObjectiveStatus = "unverified-source-field" }
quests[1527] = { id = 1527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.\n\nAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.Ihr erlernt:", sourceObjective = "Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1528] = { id = 1528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Wasser sei in Eurer Zukunft, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen des Feuers und scheint mir bereit, mit Islen zu sprechen.\n\nIslen lebt an der Küste des Brachlandes. Wenn Ihr am Ufer des Südstroms nach Süden geht, könnt Ihr sie gar nicht verfehlen...achtet auf den großen Hai! Sie kennt sich mit den Elementen aus und kann Euch etwas übers Wasser beibringen...wenn Ihr denkt, dass Ihr bereit seid.\n\nSie ist leicht zu finden, geht nur nicht zu weit nach Süden...sie ist gleich hinter Ratschet.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1529] = { id = 1529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Wasserdeuter im Brachland. Sie befindet sich an der Ostküste, südlich von Ratschet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1530] = { id = 1530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water" }
quests[1531] = { id = 1531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Wolkendeuter in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.\n\nGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.", sourceObjective = "Sucht Prate Wolkendeuter in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1532] = { id = 1532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Die Winde von Kalimdor wehen Euch entgegen und Ihr sollt zu den Mächtigsten unserer <Brüder/Schwestern> gehören. Ich sehe mit Stolz, dass Ihr so weit gekommen seid und so eine viel versprechende Zukunft habt.\n\nDas Luftelement ist schwer zu kontrollieren, doch ich vertraue darauf, dass Eure Fertigkeiten alle Hindernisse überwinden, die Euch den Weg versperren.\n\nGeht zum äußersten Südrand des Brachlandes und betretet Tausend Nadeln. Dort, weit im Osten, werdet Ihr Prate Wolkendeuter finden. Sie wird Euch mehr beibringen.", sourceObjective = "Sucht Prate Wolkendeuter in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1534] = { id = 1534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, an den Ort, den die Nachtelfen Eschental nennen. Sie liegen weit nördlich des Brachlandes.\n\nWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und das Eschental trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.\n\nBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.", sourceObjective = "Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen im Eschental und kehrt zu Brine im Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1535] = { id = 1535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.\n\nWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.", sourceObjective = "Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1536] = { id = 1536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge des Hügellands. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.\n\nDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.\n\nBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.", sourceObjective = "Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1558] = { id = 1558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinwerkdamm", description = "In der Nähe von Eisenschmiede, wo all die Zwerge und Gnome leben, gibt es einen Ort namens Loch Modan und die Zwerge haben da einen grooooßen Staudamm gebaut. Ich habe gehört, dass ist eines von den größten Dingen, die je gebaut wurden. Wow!\n\nKönnt Ihr mir den Damm in Loch Modan zeigen, bitte?! Ich glaube der heißt Stein... äh... Steinwerkdamm? Er ist riesig, so viel ist klar. Ich würde so gerne auf den großen Wasserfall heruntersehen. Ich verspreche, mich auch nicht zu weit vorzulehnen.", sourceObjective = "Begleitet Euren Schützling zum Steinwerkdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[1559] = { id = 1559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzbombenanleitung" }
quests[1560] = { id = 1560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toogas Bitte", description = "Ich habe mich vollkommen verirrt!\n\nTorta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein.\n\nWürdet Ihr so freundlich sein, mich zu Torta zurückzuführen? Sie wartet südlich vom Dampfdruckpier auf mich.", sourceObjective = "Zeigt Tooga den Weg zurück zu seiner Frau Torta.", sourceObjectiveStatus = "unverified-source-field" }
quests[1578] = { id = 1578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Front", description = "Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.\n\nDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.\n\nThorvald ist im südlichem Wachturm von Loch Modan.", sourceObjective = "Bringt 6 Kupferäxte und 6 kupferne Kettengürtel zu Thorvald im südlichen Wachturm von Loch Modan.", progress = "Ich habe keine Zeit zu plaudern. Haben wir etwas miteinander zu tun?", completion = "Ah, Entschuldigung! Ich wusste nicht, dass Ihr hier seid, um die Truppen auszurüsten. Die Sachen, die Ihr hergestellt habt, werden eine große Hilfe sein!\n\nHier sind Pläne für einige Rüstungen. Ich hoffe, Ihr findet sie nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1579] = { id = 1579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klemmmuffen", description = "Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Eisenschmiede nicht!\n\nDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemmmuffen über Bord fallen! Ich brauche meine Klemmmuffen!\n\nIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...", sourceObjective = "Bringt 8 Klemmmuffen zu Hexknall Kurbeldreh in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[1580] = { id = 1580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektropeller", description = "Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, {name}?\n\nEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!\n\nIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...", sourceObjective = "Bringt 12 Elektropeller zu Hexknall Kurbeldreh in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[1581] = { id = 1581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixiere für die Messerblatts", description = "Unser Kräuter- und Alchemieladen floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.\n\nKönnt Ihr uns helfen?\n\nWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse seltene Kräuter, die Euch nützlich sein könnten.", sourceObjective = "Bringt 6 Elixiere der Löwenstärke und 2 Elixiere der schwachen Verteidigung zu Syral Messerblatt in Dolanaar.", progress = "Hallo, {name}. Habt Ihr die Elixiere zum Tauschen?", completion = "Die sind ordentlich gemischt. Ihr nehmt Euer Handwerk ernst, {name}, und das ist wichtig für einen Alchemisten.\n\nHier sind Eure frisch gesammelten Kräuter. Benutzt sie mit Umsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1582] = { id = 1582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondscheinweste", description = "Wir in Darnassus, besonders wir Handwerker, sind sehr beschäftigt. Junge Abenteurer brennen darauf, sich in der Wildnis zu beweisen und benötigen unablässig Nachschub.\n\nWenn Ihr mir helft, meine Bestellungen an Lederwaren zu erfüllen, kann ich Euch vielleicht eine hochentwickelte Technik der Lederverarbeitung beibringen.", sourceObjective = "Bringt 1 Paar geprägte Lederhandschuhe, 5 Paar geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus.", progress = "Seid gegrüßt, {name}.", completion = "Ja, das sind gute Stücke. Ihr habt eine geschickte Hand und ein Auge für Details. Eure Zukunft als Lederverarbeiter scheint vielversprechend.\n\nHier, {name}. Lasst mich Euch das Muster für eine Mondscheinweste zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1598] = { id = 1598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gestohlene Foliant", description = "Ihr da! {name}, richtig?\n\nIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.\n\nIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.\n\nEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.\n\nEines davon war ein Buch, das ich selbst wollte, Die Macht der Leere. Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.Ihr erlernt:", sourceObjective = "Holt Die Macht der Leere für Drusilla La Salle zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1599] = { id = 1599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anfänge", description = "Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.\n\nKeine Bange, ich mache Euch keinen Vorwurf.\n\nDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.\n\nBringt mir drei Federglücksbringer von den Novizen der Frostmähnen aus der Höhle im Südwesten.Ihr erlernt:", sourceObjective = "Bringt 3 Federglücksbringer zu Alamar Grimm in Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1618] = { id = 1618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufrüstung im Rotkammgebirge", description = "Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!\n\nDas Rotkammgebirge wird immer wieder von den Schwarzfelsorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Gutmark, Euch den einen oder anderen Trick beibringen.", sourceObjective = "Tormus Tiefenschmied möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Gutmark ins Rotkammgebirge bringt.", progress = "Ich hoffe, Ihr bringt gute Nachrichten aus Eisenschmiede. Denn ich bin mit meiner Weisheit am Ende!", completion = "Danke, {name}. Das wird mir unwahrscheinlich helfen. Da die Orcs des Schwarzfelsklans von der Burg Steinwacht angreifen und die Rotkammgnolle in den Vorgebirgen im Norden lauern, muss ich ständig Rüstungen ausbessern und neue Waffen für unsere Truppen anfertigen.\n\nDie Vorräte, die Ihr gebracht habt, bescheren mir einen Moment Ruhe. Daher habe ich genug Zeit, Euch etwas beizubringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1638] = { id = 1638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung eines Kriegers", description = "Ihr habt Euch als fähiger Krieger erwiesen, {name}. Aber Ihr seid noch jung und müsst noch viel lernen.\n\nSprecht mit Harry Burlwacht... er ist meist in der Taverne \"Zum Pfeifenden Schwein\" in der Altstadt von Sturmwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.", sourceObjective = "Sprecht mit Harry Burlwacht in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1639] = { id = 1639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartleby der Trunkenbold", description = "Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.\n\nSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.\n\nHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.", sourceObjective = "Sprecht mit Bartleby.", sourceObjectiveStatus = "unverified-source-field" }
quests[1640] = { id = 1640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt Bartleby", description = "Ihr wollt was??? Ihr seid verrückt!\n\nWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", sourceObjective = "Besiegt Bartleby und redet dann mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[1641] = { id = 1641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung" }
quests[1642] = { id = 1642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1643] = { id = 1643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, {name}, besteht darin, jemanden hier in Sturmwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.", sourceObjective = "Sucht im Handelsdistrikt von Sturmwind nach Stephanie Turner.", sourceObjectiveStatus = "unverified-source-field" }
quests[1644] = { id = 1644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.\n\nMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.\n\nWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, {name}.\n\nWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.", sourceObjective = "Bringt 10 Stück Leinenstoff zu Stephanie Turner in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1645] = { id = 1645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung" }
quests[1646] = { id = 1646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1647] = { id = 1647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, {name}, ist es, jemanden hier in Eisenschmiede zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.", sourceObjective = "Sucht im Äußeren Ring von Eisenschmiede nach John Turner.", sourceObjectiveStatus = "unverified-source-field" }
quests[1648] = { id = 1648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Meine Frau und ich führen das Waisenhaus in Sturmwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Eisenschmiede und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.\n\nDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.\n\nKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.", sourceObjective = "Bringt 10 Stück Leinenstoff zu John Turner in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1649] = { id = 1649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.\n\nDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1650] = { id = 1650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.\n\nAm äußersten Ende der Endlosen Küste in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stillbrunns. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Eisenschmiede gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.\n\nEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.", sourceObjective = "Sucht Daphne Stillbrunn in Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1651] = { id = 1651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Ich wette, die kommen bald wieder, also macht Euch bereit.\n\nIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.\n\nIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.\n\nBittet das Licht um jeden erdenklichen Segen, denn...habt Ihr das gehört? Ich glaube, sie kommen.\n\nWir beziehen Position beim Haus!", sourceObjective = "Verteidigt Daphne Stillbrunn vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stillbrunn, wenn Ihr erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[1652] = { id = 1652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.\n\nEr wird eine Nachricht nach Eisenschmiede schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.\n\nOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.Ihr erlernt:", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1653] = { id = 1653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.\n\nJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.\n\nEr müsste noch in Eisenschmiede sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.", sourceObjective = "Sprecht mit Jordan Stillbrunn in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1654] = { id = 1654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.\n\nIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, {class}?", sourceObjective = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Koredelstein und bringt alles zusammen zu Jordan Stillbrunn in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1655] = { id = 1655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bailors Erzlieferung", description = "Ach, Ihr habt mich erschreckt, <Mann/Frau>! Seht Ihr nicht, dass ich nachdenke?\n\nWie war das? Jordans Lieferung... für Eisenschmiede. Ahhh, ja, ich weiß, wovon Ihr sprecht. Oger der Mo'grosh haben die Erzlieferung meines alten Freundes gestohlen. Die Karawane war auf dem Weg vom Sumpfland hierher und geriet in einen Hinterhalt. Die Wache, die den Angriff überlebte, starb vor wenigen Tagen - der Heiler kam nicht schnell genug hin.\n\nWenn Ihr die Lieferung wollt, müsst Ihr über den Loch nach Nordosten. Dort muss sie irgendwo sein.", sourceObjective = "Bringt Jordans Erzlieferung zu Bailor Steinhand in Loch Modan.", sourceObjectiveStatus = "unverified-source-field" }
quests[1656] = { id = 1656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unvollendete Aufgabe", description = "{name}, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Ebene noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus der Bluthufe abzuliefern.\n\nIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?\n\nDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.", sourceObjective = "Bringt das Bündel Felle zu Gastwirt Kauth ins Dorf der Bluthufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1657] = { id = 1657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verpestung von Süderstade", description = "Feiert die Schlotternächte mit Stil... bereitet unseren Feinden in Süderstade Kummer!\n\nNehmt eine dieser speziell angefertigten Stinkbomben. Sie sind mit einem derartig furchtbaren Schrecken gefüllt, dessen Geruch kein Mensch - oder anderes Wesen mit schwachem Gemüt - ertragen kann. Ihr müsst die Stinkbombe direkt ins Herz von Süderstade werfen, damit sie richtig wirken kann. Seid also auf eine Auseinandersetzung mit der Allianz gefasst!\n\nSolltet Ihr diese Aufgabe bewältigt haben, kehrt zu mir zurück... es ist ein Beitrag zu unserer Befreiung!", sourceObjective = "Werft drei Stinkbomben der Verlassenen ins Herz von Süderstade im Hügelland und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1658] = { id = 1658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bespitzelt das Fest des Weidenmanns", description = "Ich brauche mutige Freiwillige, die nach Tirisfal ziehen und das Fest des Weidenmanns auskundschaften. Ich möchte nicht lügen - diese Mission ist äußerst gefährlich. Die Wachen des Fests werden besonders bösartig sein. Trotzdem, wir müssen in Erfahrung bringen, wie groß das Fest dieses Jahr ist und wie viel Schaden die Verlassenen dieses Mal während der Schlotternächte anrichten.\n\nSolltet Ihr dabei sein, dann geht nach Tirisfal und kundschaftet das Fest aus. Kehrt mit den Informationen zu mir zurück und ich werde für eine angemessene Belohnung sorgen.", sourceObjective = "Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Unteroffizier Hartman in Süderstade zurück, sobald Ihr Eure Mission erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1661] = { id = 1661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant des Adels", description = "Ich grüße Euch erneut, {name}. Ich bin stolzer als jemals zuvor, Euch <Bruder/Schwester> nennen zu können - Euer Engagement ist ein Tribut an uns alle.\n\nDie Zeit ist für mich gekommen, Euch ein wunderbares Geschenk zu übergeben. Wisset aber, dass ich es Euch fürs Erste zwar frei gebe, später jedoch, falls die Zeit es erlaubt, wird dies eine viel größere Herausforderung für alle Paladine sein, die sich dazu entscheiden, meinen Auftrag anzunehmen.\n\nSprecht erneut mit mir und ich werde Euch einen großen Segen gewähren.Ihr erlernt:", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1665] = { id = 1665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartlebys Becher", description = "Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.", sourceObjective = "Bringt Bartlebys Becher zu Burlwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1666] = { id = 1666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschall Haggard", description = "Ihr habt einige Kampftechniken gelernt, braucht aber noch eine anständige Waffe. Ich wette, Marschall Haggard könnte Euch helfen, wenn Ihr mit ihm sprecht.\n\nMarschall Haggard lebt in einem Anwesen im Wald von Elwynn, beim Holzfällerlager des Osttals. Er ist jetzt im Ruhestand, hat aber in seiner Laufbahn eine Menge Ausrüstung gesammelt.\n\nLasst ihn wissen, dass ich Euch geschickt habe, und mit etwas Glück hat er eine Waffe für Euch übrig.", sourceObjective = "Sprecht mit Marschall Haggard.", sourceObjectiveStatus = "unverified-source-field" }
quests[1667] = { id = 1667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stumpfzahn Jack", description = "Burlwacht hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch...\n\nVor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack. Es war dunkel und er trug einen Wappenrock von Sturmwind, daher dachte ich, er sei Marschall Dughan. Er sagte, er braucht meinen alten Marschallstern aus Sturmwind und ich gab ihm diesen... dann lachte er und lief weg, ehe ich ihn packen konnte!\n\nBringt mir meinen Stern! Stumpfzahn Jack hat ihn wahrscheinlich in seinem Lager im Süden versteckt.", sourceObjective = "Holt Marschall Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marschall Haggard zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1678] = { id = 1678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vejrek", description = "Wenn Ihr es in den Reihen der Krieger zu etwas bringen wollt, müsst Ihr zäh sein. Ich kann Euch neue Kampftechniken beibringen, aber zuvor müsst Ihr mir beweisen, dass Ihr gegen richtige Feinde bestehen könnt.\n\nVejrek ist der härteste Troll, den Ihr in dieser Gegend findet. Ihn müsst Ihr besiegen. Er hat eine Hütte im Vorgebirge südlich der Höhle der Frostmähnen.\n\nBringt mir Vejreks Kopf, dann weiß ich, dass Ihr Mumm habt.", sourceObjective = "Bringt Vejreks Kopf zu Muren Sturmlanze in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1679] = { id = 1679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muren Sturmlanze", description = "Hallo, Krieger! Ihr seid viel versprechend, aber dennoch müsst Ihr ein paar Tricks lernen, und Muren Sturmlanze ist genau der Zwerg, der sie Euch beibringen kann.\n\nIhr findet Muren in der Halle der Waffen im Militärviertel von Eisenschmiede. Sprecht mit ihm, wenn Ihr bereit seid zu lernen, was es heißt, ein Krieger zu sein.", sourceObjective = "Sprecht mit Muren Sturmlanze.", sourceObjectiveStatus = "unverified-source-field" }
quests[1680] = { id = 1680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormus Tiefenschmied", description = "Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Tiefenschmied. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.\n\nIhr findet Tormus hier in Eisenschmiede bei der Großen Schmiede.", sourceObjective = "Sprecht mit Tormus Tiefenschmied.", sourceObjectiveStatus = "unverified-source-field" }
quests[1681] = { id = 1681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbands Truppenlager", description = "Mein Mentor Sturgy Eisenband hatte ein Lager südlich des Helmsbettsees im östlichen Dun Morogh. Dort lehrte er die Schmiedekunst und er war der Beste.\n\nAber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Meister Eisenband nannte es Umbralerz und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande Dunkeleisenzwerge sein Lager an. Sie töteten alle!\n\nBegebt Euch zu Eisenbands Lager, {name}, und rächt den Tod meines Meisters. Und bringt mir die Ladung Umbralerz, die all das auslöste.", sourceObjective = "Bringt eine Ladung Umbralerz zu Tormus Tiefenschmied in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1682] = { id = 1682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen aus grauem Eisen" }
quests[1683] = { id = 1683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorlus Elendshuf", description = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.\n\nDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.\n\nSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.\n\nDer Weg zum Mondbrunnen ist gut verborgen, {name}, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", sourceObjective = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1684] = { id = 1684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elanaria", description = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.\n\nDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", sourceObjective = "Sprecht mit Elanaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[1685] = { id = 1685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakins Beschwörung", description = "Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.\n\nIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.\n\nIhr findet ihn im Keller der Taverne 'Zum Geschlachteten Lamm'. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1686] = { id = 1686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eluras Schemen", description = "Ihr habt viel gelernt, {name}. Jetzt fertigen wir Euch eine Waffe an. Die Waffe eines Kriegers.\n\nDazu müsst Ihr nach Dunkelküste reisen.\n\nVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten Eluniterz sanken auf den Meeresgrund.\n\nAls Erstes müsst Ihr den Wächter des Elunits besiegen, Eluras Schemen. Sie war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Besiegt sie, nehmt Ihr das Medaillon ab und sammelt die verlorenen Elunitkisten ein.", sourceObjective = "Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1687] = { id = 1687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gruselige Leuchtturm", description = "Abends erzählen uns die Matronen manchmal Gruselgeschichten. Die sind spitze! Einmal haben sie uns von einem Geist erzählt, der in einem Leuchtturm in Westfall spukt. Er soll einmal ein Piratenkapitän gewesen sein, dessen Schiff ihm von anderen Piraten weggenommen wurde. Wow!\n\nKönnen wir uns bitte den Leuchtturm in Westfall anschauen? Ich will nachgucken, ob der Geist des Kapitäns noch immer dort ist! Ich bleibe auch immer nah bei Euch. Ich renn' auch bestimmt nicht weg oder so was.", sourceObjective = "Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1688] = { id = 1688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surena Caledon", description = "Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!\n\nDas diebische Weib brannte mit einem Schläger durch, Erlan Tragmehr. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.\n\nIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackbrunns Kürbisbeet. Bringt wieder, was mir gehört.", sourceObjective = "Beschafft Surenas Halsreif für Gakin den Dunkelbinder in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1689] = { id = 1689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ihr habt meinen Halsreif zurückgebracht und Surena bezwungen und damit gezeigt, dass Ihr mindestens ebenso begabt seid, wie sie es war.\n\nNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.\n\nIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.Ihr erlernt:", sourceObjective = "Beschwört mithilfe des Blutsteinhalsreifs einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsreif zu Gakin dem Dunkelbinder in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1690] = { id = 1690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenläufergerechtigkeit", description = "Ihr da! Für Euch ist es an der Zeit, ein großer Helfer der Gadgetzan Water Company zu sein.\n\nDie Wüstenläufernomaden draußen in der Tanariswüste haben fast alle Brunnen erobert! Ohne Zugang zu den Brunnen wird unser Wasservorrat im Handumdrehen schwinden. Wenn Ihr Euch unsere Dankbarkeit verdienen wollt, dann helft uns, diese Nomaden der Gerechtigkeit zuzuführen!\n\nBegebt Euch von hier Richtung Osten und schaltet zehn Banditen und Diebe der Wüstenläufer aus und meldet Euch dann umgehend wieder bei mir. Gerechtigkeit wartet auf keinen Mann... keinen Goblin... ach, legt einfach los!", sourceObjective = "Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgenritzel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1691] = { id = 1691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Wüstenläufergerechtigkeit", description = "Wir müssen uns jetzt die stärkeren Ränge der Wüstenläufernomaden vornehmen. Ihr habt bisher gute Arbeit geleistet, aber wenn wir diese Brunnen zurückerobern wollen, dann wäre es gut, wenn uns dabei so wenig Nomaden wie möglich gegenüberstünden!\n\nDieses Mal müsst Ihr ihre Schurken, Auftragsmörder und Schattenmagier erledigen. Ihr werdet sie östlich und südöstlich von hier finden.\n\nIch werde Euch nichts vormachen - das ist eine schlimme Bande. Tut dies für uns, dann sind wir auf dem besten Weg, uns das zurückzuholen, was rechtmäßig uns gehört!", sourceObjective = "Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgenritzel in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[1692] = { id = 1692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmied Mathiel", description = "Ich habe das Elunit, das Ihr gesammelt habt, in eine Kiste gelegt. Bringt sie zum Schmied Mathiel, er wird eine Elunitwaffe für Euch anfertigen.\n\nMathiel ist im Süden, an der anderen Seite dieses Gebäudes zu finden.", sourceObjective = "Bringt das Behältnis mit Elunit zu Schmied Mathiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1693] = { id = 1693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen aus Elunit" }
quests[1698] = { id = 1698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorus Gerstenbräu", description = "Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet. Er wartet im Gasthaus von Seenhain im Rotkammgebirge und verspricht jedem, der seine Prüfung besteht, eine hohe Belohnung.", sourceObjective = "Sprecht mit Yorus Gerstenbräu.", sourceObjectiveStatus = "unverified-source-field" }
quests[1699] = { id = 1699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rethbanspießrutenlauf", description = "Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...\n\nIhr müsst binnen einer Stunde zurück sein.\n\nGanze Heerscharen von Rotkammgnollen versperren den Weg.\n\nVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!\n\nWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?", sourceObjective = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.\n\nIhr dürft nicht sterben und Euren Geist befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[1700] = { id = 1700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand Elmore", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zu Grimand Elmore geschickt werden. Er ist hier im Zwergendistrikt, im Waffenladen.\n\nUnd duckt Euch, wenn Ihr ihm die gebt. Er bildet sich ungeheuer viel auf seine Fertigkeiten ein. Es wird ihm nicht gefallen, etwas von mir zu lernen...", sourceObjective = "Bringt Furens Notizen zu Grimand Elmore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1701] = { id = 1701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuergehärteter Panzer", description = "Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstungen herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.\n\nWas sagt Ihr dazu, {name}? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.", sourceObjective = "Sammelt die Materialien, die Furen Langbart benötigt, und bringt sie zu ihm nach Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1702] = { id = 1702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schildschmied", description = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, {name}. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...\n\nAber sie ist in Sturmwind.\n\nSprecht mit meinem Freund Furen Langbart im Zwergendistrikt von Sturmwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.\n\nHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.", sourceObjective = "Bringt das Fässlein mit Gerstenbräu zu Furen Langbart.", sourceObjectiveStatus = "unverified-source-field" }
quests[1703] = { id = 1703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiel", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zum Schmied Mathiel geschickt werden. Er lebt in Darnassus. Das ist weit weg, aber ich bin sicher, er wird dankbar sein, wenn er erfährt, was ich gelernt habe.", sourceObjective = "Bringt Furens Notizen zu Mathiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1704] = { id = 1704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort Spannsplint", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte, und brauche jemanden, der sie zu Klockmort Spannsplint bringt. Er ist ein gnomischer Schmied in Eisenschmiede, und wenn er herausfindet, was ich herausgefunden habe...Ich wette, er reißt sich vor Aufregung selbst den Bart aus.", sourceObjective = "Bringt Furens Notizen zu Klockmort Spannsplint.", sourceObjectiveStatus = "unverified-source-field" }
quests[1705] = { id = 1705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennendes Blut", description = "Ich gebe nur ungern zu, dass Furen tatsächlich etwas gefunden haben könnte. Aber um ganz sicher zu sein, muss ich seine Techniken an einem neuen Rüstungsteil erproben. Wenn Ihr mir mit den Materialien helft, {name}, könnt Ihr die Rüstung haben.\n\nUm die Rüstung herzustellen benötige ich Proben von brennendem Blut und brennendem Felsen.\n\nDie findet man meines Wissens nur im Dämmerwald. Die Worgs der Nachtheuler in der Mine von Rolands Verdammnis haben brennendes Blut, und Bauchreißer, ihr Anführer, wird den Fels haben.\n\nMöge das Schicksal Euch Schnelligkeit gewähren {name}.", sourceObjective = "Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1706] = { id = 1706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimands Rüstung" }
quests[1707] = { id = 1707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbeutelkopfgeld", description = "Seid gegrüßt, {name}, mein Name ist Lochbeutel, und wir haben einen wichtigen Auftrag für Euch, wenn Ihr bereit seid! Hussah!\n\nNichts würde mir als altgedientem Leitungshahnmaschinisten mehr gefallen, als Euch jeden Wasserbeutel eines Wüstenläufers abzunehmen, den Ihr draußen in der Wüste findet. Das ist ja ohnehin unser Wasser - die Nomaden haben es einfach nur gestohlen! Die Gadgetzan Water Company bietet Euch ein offizielles Überlebenspaket für jeweils fünf, die Ihr abliefert. Am wichtigsten ist aber, dass Ihr Gadgetzan selbst helft!", sourceObjective = "Bringt Leitungshahnmaschinist Lochbeutel in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", sourceObjectiveStatus = "unverified-source-field" }
quests[1708] = { id = 1708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenkoralle", description = "Ich möchte Furen Langbarts neue Techniken an einer eigenen Rüstung erproben. Und weil Ihr Furen geholfen habt und er mir, sollt Ihr die Rüstung bekommen, wenn sie fertig ist!\n\nUm das Teil zu beenden, brauche ich eine spezielle Koralle, Sengkoralle. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im Sumpfland.\n\nBringt mir genügend Sengkoralle und ich mache mich gleich an die Arbeit. Und beeilt Euch, {name}. Ich brenne so sehr darauf, endlich anzufangen, dass meine Zehen jucken!", sourceObjective = "Bringt 20 Ladungen Sengkoralle zu Klockmort Spannsplint in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1709] = { id = 1709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmorts Kreation" }
quests[1710] = { id = 1710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenverbrannte Schalen", description = "Mein Kollege, Furen Langbart, hat eine Entdeckung gemacht, die ich schnellstens ausprobieren möchte. Ich möchte sie an einer neuen Rüstung erproben, an der ich forsche, denn ich glaube, Furens Techniken werden grandiose Ergebnisse erzielen.\n\nWerdet Ihr mir helfen? Wenn Ihr sammelt, was ich zur Herstellung der Rüstung brauche, fertige ich für Euch auch eine an.\n\nIch brauche sonnenverbrannte Eierschalen der Steilhangwyvern, die am Steilhang in Tausend Nadeln hausen. Sucht unter den Nestern nach den Schalen und kommt zu mir zurück, wenn Ihr eine ausreichende Menge habt.", sourceObjective = "Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1711] = { id = 1711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiels Rüstung" }
quests[1712] = { id = 1712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyclonian", description = "Ich beobachte diesen Ort seit Ewigkeiten. Ich beobachte, damit ich eines Tages den großen Cyclonian fallen sehen kann. Doch ich fand noch keinen Helden, der den Windlord besiegen konnte.\n\nVielleicht seid Ihr dieser Held.\n\nBeweist es mir. Sammelt die Gegenstände, die ich brauche, um Cyclonian zu beschwören, dann weiß ich, dass Ihr ein großer Krieger seid. Vielleicht könnt Ihr ihn besiegen und sein Wirbelherz bekommen.\n\nWenn ja, übertrage ich die Macht des Herzens in eine Waffe und schenke Euch diese Waffe.\n\nHier ein Pergament mit den Gegenständen, die ich benötige.", sourceObjective = "Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac.", sourceObjectiveStatus = "unverified-source-field" }
quests[1713] = { id = 1713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung", description = "Ich bin bereit, das Ritual zur Beschwörung Cyclonians durchzuführen. Wenn er beschworen ist, müsst Ihr ihn besiegen und sein Wirbelherz nehmen. Ich werde es benutzen, um eine Waffe mit Cyclonians Macht zu stärken.\n\n{name}, seid Ihr bereit, dem Windlord zu trotzen?", sourceObjective = "Bringt das Wirbelherz zu Bath'rah dem Windbehüter.", sourceObjectiveStatus = "unverified-source-field" }
quests[1714] = { id = 1714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz der Verbannung" }
quests[1715] = { id = 1715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Geschlachteten Lamm", description = "Hmph. Früher wurden alle Hexenmeister in Khaz Modan unter der Aufsicht der Meister von Gnomeregan ausgebildet, doch jetzt, wo wir gezwungen wurden, in dieses Rattenloch in Eisenschmiede zu ziehen und Magni beschloss, uns genau zu beobachten, sind wir gezwungen, unsere Novizen zur Ausbildung nach Sturmwind zu schicken.\n\nZum Glück ist Gakin kein Tölpel, daher werdet Ihr lernen, was Ihr wissen müsst. Dennoch bringt es mein Blut zum Kochen!\n\nWie auch immer, Ihr findet Gakin im Keller des Geschlachteten Lamms in Sturmwind.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1716] = { id = 1716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Ein Sukkubus ist ein Verschlinger der Seelen, Zerstörer der Herzen, Bezwinger des Geistes. Er kennt nur das Böse.\n\nDies ist die Kreatur, die Ihr beschwören und beherrschen lernt, doch ohne Anreiz kann sie nicht in unsere Welt gebracht werden.\n\nMit einem Symbol der Liebe als Köder wird er gewiss auf Euren Ruf reagieren. Dann könnt Ihr ihn besiegen und zu Eurem Werkzeug machen.\n\nEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.", sourceObjective = "Sprecht mit Takar dem Seher im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1717] = { id = 1717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakins Beschwörung", description = "{name}! Ich hätte nicht erwartet, Euch in der Gegend zu sehen, wurde aber angewiesen, nach Euch Ausschau zu halten.\n\nHöchste Zeit, dass Eure Ausbildung fortgesetzt wird. Beim nächsten Besuch in Sturmwind solltet Ihr bei Gakin reinschauen. Er wird Euch erwarten.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1718] = { id = 1718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Inselbewohner", description = "Euer Ruf als Krieger wächst, {name}. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.\n\nVor der Küste des Brachlandes, südlich von Ratschet, liegt eine Insel. Sie heißt Prügeleiland und ist ein Treffpunkt für Krieger.\n\nGeht dorthin und kämpft.\n\nSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.\n\nUm das Prügeleiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.", sourceObjective = "Sprecht mit Klannoc Macleod.", sourceObjectiveStatus = "unverified-source-field" }
quests[1719] = { id = 1719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ringkampf", description = "Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügeleiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.\n\nGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flachkopf, dass Ihr bereit seid, und er schickt Euch Herausforderer.\n\nWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.", sourceObjective = "Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügeleiland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1738] = { id = 1738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzholz", description = "Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.\n\nIm Krieg der Ahnen fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.\n\nEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes vom Eschental.", sourceObjective = "Holt das Herzholz aus dem Eschental und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1739] = { id = 1739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.\n\nSeid vorsichtig, {name}, Sukkuben haben schon den stärksten Geist unterjocht.\n\nWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.Ihr erlernt:", sourceObjective = "Beschwört mithilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im Geschlachteten Lamm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1740] = { id = 1740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kugel von Soran'ruk", description = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.\n\nViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.\n\nDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolythen des Schattenhammers in der Tiefschwarzen Grotte benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Schattenfang. Sucht sie, dann kann ich sie zusammenfügen...", sourceObjective = "Sucht 3 Fragmente von Soran'ruk und 1 großes Fragment von Soran'ruk und bringt sie zu Doan Karhan im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1758] = { id = 1758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolythen und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Krom Starkarm Euch dabei helfen. Heute ist er ein fahrender Hexenmeister, hortet alte Schriften und hängt in der Bibliothek von Eisenschmiede herum.", sourceObjective = "Sprecht mit Krom Starkarm in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1778] = { id = 1778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Sturmwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, {class}.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1779] = { id = 1779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich möchte, dass Ihr das nehmt, {name}. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.\n\nMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.\n\nNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.", sourceObjective = "Nehmt das Symbol des Lebens und sprecht mit Muiredon Kriegshammer in Eisenschmiede.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1780] = { id = 1780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, {class}. Es kommt nicht oft vor, dass <Männer/Frauen> Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Sturmwind die Bedürftigen nicht im Stich lassen.\n\nLebt wohl.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1781] = { id = 1781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Nehmt das, {name}. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.\n\nMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.\n\nNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.", sourceObjective = "Bringt das Symbol des Lebens zu Gazin Tenorm in Sturmwind.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1782] = { id = 1782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furens Rüstung" }
quests[1783] = { id = 1783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbettsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.\n\nNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.\n\nNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.\n\nKönnt Ihr helfen, {name}?", sourceObjective = "Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1784] = { id = 1784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Hauptmann ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.\n\nEinige im Rat von Eisenschmiede glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.\n\nBeschafft eines dieser Manuskripte und bringt es zu Muiredon, {name}.", sourceObjective = "Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbettsee und kehrt zu Muiredon Kriegshammer in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1785] = { id = 1785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.\n\n's Licht soll mit Euch sein, {class}. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.Ihr erlernt:", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1786] = { id = 1786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.\n\nAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.\n\nHenze wehrte sie ab, derweil ich entkam...der elende Narr muss immer den Helden spielen.\n\nEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, {name}?", sourceObjective = "Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1787] = { id = 1787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.\n\nMomentan bin ich nicht in der Verfassung zu kämpfen, {name}. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?\n\nWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.", sourceObjective = "Beschafft ein Manuskript der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1788] = { id = 1788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!\n\nNochmals danke, {name}. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.Ihr erlernt:", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1789] = { id = 1789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Symbol des Lebens" }
quests[1790] = { id = 1790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Symbol des Lebens" }
quests[1791] = { id = 1791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Windbehüter", description = "Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.\n\nSprecht mit Bath'rah dem Windbehüter. Das ist ein Trolleinsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.\n\nUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.", sourceObjective = "Sprecht mit Bath'rah dem Windbehüter.", sourceObjectiveStatus = "unverified-source-field" }
quests[1792] = { id = 1792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelwaffe" }
quests[1793] = { id = 1793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Ehre" }
quests[1794] = { id = 1794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit" }
quests[1795] = { id = 1795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Wenn Ihr hinreichend vorbereitet seid, sollten wir beginnen. Lasst mich Euch den Vorgang erklären.\n\nIch beginne damit, dass ich den Standard-Beschwörungskreis erstelle. Wenn das geschehen ist, werden meine Akolythen mit den Kanalisierungsruten den größeren Kreis erstellen.\n\nIst das abgeschlossen, lest Ihr die Zauberformel aus dem Folianten der Kabale und der Teufelsjäger erscheint. Seid vorsichtig, {name}. Ein Teufelsjäger ist ein mächtiger Widersacher. Ich möchte nicht, dass er Euch einen Kopf kürzer macht.Ihr erlernt:", sourceObjective = "Beschwört mithilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratschet zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1796] = { id = 1796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Der erste Gegenstand, bei dessen Erschaffung ich Euch helfen werde, ist eine Robe. Ihr werdet die Gegenstände für mich sammeln und wir werden sie zusammensetzen. Vorausgesetzt Ihr seid erfolgreich, werdet Ihr danach den ersten von vielen Gegenständen haben, die Euch mächtiger machen und Euch bei Eurem Kampf helfen werden.\n\nFür den Anfang müsst Ihr in den Besitz der Roben von Arcana kommen. Ein Schneider kann sie für Euch machen oder vielleicht könnt Ihr eine von jemandem kaufen... am meisten würde es mich beeindrucken, wenn Ihr sie selbst herstellen könntet... aber wie auch immer, bringt mir die Roben und dann machen wir weiter.", sourceObjective = "Bringt die Roben von Arcana zu Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1798] = { id = 1798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Es ist Zeit, dass Ihr die Beschwörung eines Teufelsjägers lernt, {name}. Ich habe nicht die erforderlichen Reagenzien und Gegenstände, um Euch hier zu unterrichten, daher müsst Ihr einen anderen aus unserem inneren Kreis aufsuchen, nämlich Strahad Farsan.\n\nEr hat sich im Goblinhafen von Ratschet niedergelassen. Ich werde ihn von Eurer Ankunft in Kenntnis setzen lassen.", sourceObjective = "Sprecht mit Strahad Farsan im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1799] = { id = 1799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Kugel von Orahil", description = "Gut, dann können wir beginnen.\n\nIhr müsst als Erstes mit meinen Akolythen im Inneren sprechen. Wählt einen ihrer Wege und folgt ihm - sie werden Euch alles erklären.\n\nAls Zweites müsst Ihr nach Desolace reisen und eine Höllenkugel von einem der Hexenmeister beim Zirkel der Mannoroc holen. Diese Kugel werdet Ihr mit der Hilfe einer Magierin namens Tabetha tief in den südlichen Düstermarschen reinigen. Sie wird Euch aufgrund unserer gemeinsamen Vergangenheit helfen.\n\nKommt erst zurück, wenn Ihr beide Dinge erledigt habt, um die ich Euch gebeten habe.", sourceObjective = "Sprecht mit Menaras Akolythen im Inneren des Turms über Ratschet und wählt einen ihrer Wege, um ihm zu folgen.\n\nBringt danach eine Höllenkugel zu Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1800] = { id = 1800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thronsaal von Lordaeron", description = "Wenn wir brav sind und die Hausarbeiten ordentlich machen, erzählen uns die Waisenmatronen oft Geschichten von großen Schlachten und darüber, wie Lordaeron fiel und wie der böse Arthas seinen eigenen Vater umbrachte, nur um König zu werden.\n\nEr hatte keine Ehre, {name}! Wenn ich erst einmal groß und ein mächtiger Krieger der Horde bin, wird mein Schwert durch die Ehre geleitet werden; niemals durch das Böse!\n\nWürdet Ihr mit mir den Thronsaal besuchen, bitte? Er befindet sich kurz vor dem Abgang, über den man nach Unterstadt heruntergeht.", sourceObjective = "Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1801] = { id = 1801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of the Cabal" }
quests[1802] = { id = 1802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Er ist verschollen, aber man glaubt zu wissen, wo man ihn finden könnte.\n\nNur eine Kopie wurde jemals angefertigt, und die wurde einst beschädigt, eine Vielzahl von Seiten herausgerissen. Man munkelt, dass er irgendwie den Zentauren von Tausend Nadeln in die Hände gefallen sein soll.\n\nDer Rest ging an der Küste westlich von Süderstade verloren, als er per Schiff zum Hafen von Menethil hätte transportiert werden sollen. Er kam nie an.\n\nAls Gegenleistung für dieses Wissen verlange ich nur, dass Ihr ihn findet und mir zur Ansicht bringt.", sourceObjective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Starkarm in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1803] = { id = 1803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Ah! Ich sehe, Ihr seid ein Hexenmeister, der meinen Geschmack teilt. Den Folianten der Kabale zu beschaffen ist ein würdiges Ziel. Habt Ihr gewusst, dass er sich einst innerhalb der Mauern von Lordaeron befand? Aber er wurde beschädigt, fast die Hälfte der Seiten herausgerissen. Wer würde so eine abscheuliche Tat begehen?\n\nDiese Hälfte ist verschollen, doch man munkelt, sie soll den Zentauren von Tausend Nadeln in die Hände gefallen sein.\n\nDer Rest des Textes sollte nach Eisenschmiede gebracht werden, ging aber während der Überfahrt an der Westküste von Süderstade verloren.", sourceObjective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1804] = { id = 1804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Ach ja, es ist recht schwer, ihn aus der Hand zu geben. Aber Ihr habt ihn gefunden und natürlich Wichtigeres damit zu tun. Vergesst nur nicht, Strahad zu sagen, dass ich eine Kopie haben möchte.\n\nWährend Ihr fort wart, hat er eine Nachricht für Euch geschickt. Er sagte mir, damit seine Akolythen bei der Beschwörung helfen können, müsst Ihr drei Kanalisierungsruten beschaffen.\n\nEr weiß vielleicht nicht, wo man die findet, aber ich! Sie wurden zuletzt von den Orcs des Drachenmalklans im Sumpfland verwendet. Ich würde mich mal mit ihren Zauberern in Verbindung setzen!", sourceObjective = "Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1805] = { id = 1805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Das ist einer der interessantesten Texte, die ich in den letzten Jahren gelesen habe. Die Auswahl hier ist nicht sonderlich groß - zum Großteil sind es Bücher über Geografie - und ich habe sie schon alle gelesen. Hoffentlich schickt mir Strahad eine Kopie dieses Folianten, wenn er die Chance dazu hat.\n\nDa wir gerade von ihm sprechen: während Ihr fort wart, habe ich eine Nachricht von ihm erhalten. Für Eure Aufgabe müsst Ihr drei Ruten des Kanalisierens beschaffen.\n\nWeil Ihr mir diesen Text gezeigt habt, weihe ich Euch in ein Geheimnis ein: Ihr findet die Ruten bei den Orcs des Drachenmalklans im Sumpfland.", sourceObjective = "Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1806] = { id = 1806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.\n\nWenn wir fertig sind, werdet Ihr viel besser gerüstet sein, das Licht zu verteidigen, als bisher, das schwöre ich Euch.\n\nIch will ehrlich sein, {name}, wenn ich die Ergebnisse Eurer Taten sehe, erfüllt mich ein gewisser Neid. Doch das Wissen, dass ich auf meine bedeutende Weise zu Euren Abenteuern beitragen kann, erfüllt mich mit Freude.", sourceObjective = "Wartet, bis Jordan Stillbrunn eine Waffe für Euch geschmiedet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1818] = { id = 1818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Dillinger", description = "Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der Dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.\n\nTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.", sourceObjective = "Sprecht mit Todeswache Dillinger in Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[1819] = { id = 1819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulag der Spalter", description = "Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.\n\nWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. \n\nBefreit und tötet ihn.\n\nAktiviert den Schädelsteinauslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.\n\nUnd dann... seid bereit, {name}.", sourceObjective = "Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[1820] = { id = 1820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Coleman", description = "Ihr habt Euren Wert für die Dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.\n\nColeman Heller wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.\n\nIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.", sourceObjective = "Sprecht mit Coleman Heller.", sourceObjectiveStatus = "unverified-source-field" }
quests[1821] = { id = 1821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamand-Erbstücke", description = "Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.\n\nUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!\n\nDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.", sourceObjective = "Bringt Coleman Heller die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand.", sourceObjectiveStatus = "unverified-source-field" }
quests[1822] = { id = 1822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbstückwaffe" }
quests[1823] = { id = 1823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Ruga", description = "Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Rachtotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.\n\nEr wartet auf Krieger, die seinem Ruf folgen.", sourceObjective = "Sprecht mit Ruga Rachtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[1824] = { id = 1824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung auf dem Feld der Riesen", description = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.\n\nBringt mir ihre noch zuckenden Fühler und vergeudet keine Zeit, {name}, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.", sourceObjective = "Bringt 5 zuckende Fühler zu Ruga Rachtotem im Camp Taurajo.", sourceObjectiveStatus = "unverified-source-field" }
quests[1825] = { id = 1825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Thun'grim", description = "Thun'grim Brandblick, ein berühmter orcischer Schmied, hat von Euren fortgesetzten Heldentaten im Dienst der Horde gehört. Er möchte eine Rüstung für Euch anfertigen und bittet, dass Ihr umgehend mit ihm sprecht.\n\nThun'grims Lager liegt östlich des Wegekreuzes im Brachland.", sourceObjective = "Sprecht mit Thun'grim Brandblick im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1838] = { id = 1838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Rüstung", description = "Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.\n\nAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, {name}. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.\n\nHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.", sourceObjective = "Bringt Thun'grim Brandblick 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston.", sourceObjectiveStatus = "unverified-source-field" }
quests[1839] = { id = 1839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ula'elek und die brutalen Stulpen", description = "Der Trollschmied Ula'elek wird die brutalen Stulpen für Euch anfertigen. Er wohnt mit seinen Dunkelspeerbrüdern in Durotar in Sen'jin und erwartet Eure Ankunft.", sourceObjective = "Sprecht mit Ula'elek in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1840] = { id = 1840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orm Steinhuf und der brutale Helm", description = "Orm Steinhuf wird ob seiner Fertigkeiten hoch geachtet. Er wird den brutalen Helm für Euch machen.\n\nSucht ihn in Donnerfels beim Teich nahe dem großen, zentralen Totem der Stadt.", sourceObjective = "Sprecht mit Orm Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1841] = { id = 1841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velora Nachtens und die brutalen Beinschützer", description = "Es heißt, vor ihrem Tod hätte Velora Nachtens zu den besten Rüstungsschmieden von Lordaeron gehört. Offenbar konnte der Tod ihrem Talent nichts anhaben. Sprecht mit Velora - sie wird die brutalen Beinschützer für Euch machen.\n\nVelora geht ihrem Gewerbe in Unterstadt unterhalb von Lordaeron nach, im Handwerksviertel.", sourceObjective = "Sprecht in Unterstadt mit Velora Nachtens.", sourceObjectiveStatus = "unverified-source-field" }
quests[1842] = { id = 1842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrhufe", description = "Ich kann Euch ein Paar brutale Stulpen machen, denen große Magie innewohnen wird. Doch vorher müsst Ihr diese Magie sammeln und mir bringen.\n\nDie Satyrn halten sich im nordöstlichen Teil des Eschentals auf wegen der Macht, die dem Wald innewohnt. Sie nähren sich an seiner Reinheit, saugen sie ab und verderben sie. An den geschwollenen, ungespaltenen Hufen erkennt man, welche Satyrn die meiste Magie des Eschentals aufgenommen haben.\n\nDiese Hufe besitzen große Macht. Ich brauche sie, um Eure Stulpen anzufertigen.", sourceObjective = "Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1843] = { id = 1843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Stulpen" }
quests[1844] = { id = 1844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimärenhorn", description = "Ich mache Euch den Helm, doch vorher müsst Ihr mir zeigen, dass Ihr würdig seid.\n\nEingebettet in die südwestlichen Ausläufer des Steinkrallengebirges liegt das Verbrannte Tal. Das war einst ein fruchtbarer Ort, ist aber heute besudelt und voll Asche. Die Kreaturen, die dort noch hausen, sind wahnsinnig vor Schmerz und Verzweiflung.\n\nAn diesen Ort schicke ich Euch, {name}.\n\nIhr müsst zum Verbrannten Tal reisen und eine Schimärenmatriarchin suchen. Tötet sie, erlöst sie von ihrem Elend. Bringt mir ihr galvanisiertes Horn als Beweis, dann mache ich den Helm für Euch.", sourceObjective = "Bringt ein galvanisiertes Horn zu Orm Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1845] = { id = 1845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutaler Helm" }
quests[1846] = { id = 1846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schienbeinknochen der Drachenmalorcs", description = "Um brutale Beinschützer zu machen, brauche ich eine Stütze aus stabilem Schienbeinknochen. Die Orcs des Drachenmalklans im Sumpfland haben hübsche, dicke Schienbeinknochen. Die brauche ich.\n\nAber sie müssen stabil sein. Prüft die Schienbeinknochen unbedingt, wenn Ihr sie einsammelt. Wenn Ihr sie mit bloßen Händen zerbrechen könnt, sind sie nicht stabil genug für mich.", sourceObjective = "Bringt 8 stabile Schienbeinknochen eines Drachenmalorcs zu Velora Nachtens in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1847] = { id = 1847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Beinschützer" }
quests[1848] = { id = 1848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Halsberge" }
quests[1858] = { id = 1858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerschmetterte Hand", description = "Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.\n\nDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.", sourceObjective = "Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1859] = { id = 1859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therzok", description = "Sprecht leiser, {name}. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.\n\nSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.\n\nHabe ich Recht?\n\nWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.", sourceObjective = "Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1860] = { id = 1860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Jennea", description = "Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Sturmwind und dem Wald von Elwynn von entscheidender Bedeutung.\n\nJennea Haubitz kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Sturmwind. Ihr solltet Euch eiligst zu ihr begeben.", sourceObjective = "Sprecht in Sturmwind mit Jennea Haubitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1861] = { id = 1861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelsee", description = "Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden. Einige von uns fürchten das Schlimmste.\n\nAber davon werde ich Euch später mehr erzählen. Im Augenblick müsst Ihr Informationen für uns sammeln.\n\nHier, nehmt dieses Fläschchen. Geht zum Wasserfall des Spiegelsees, südwestlich der Tore von Sturmwind, und holt dort eine Probe des Wassers. Bringt sie mir, damit ich die magische Besudelung messen kann.", sourceObjective = "Bringt eine Probe des Spiegelseewassers zu Jennea Haubitz in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1878] = { id = 1878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbeutelkopfgeld" }
quests[1879] = { id = 1879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Bink", description = "{name}! Bink, meine gnomische Kollegin in Eisenschmiede, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr <ein Magier/eine Magierin>, {name}?\n\nWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Eisenschmiede in der Halle der Mysterien im mystischen Krieg.", sourceObjective = "Sprecht mit Bink in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1880] = { id = 1880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magitastischer Gizmonitor", description = "Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit. Und Wissen... viel, viel Wissen!\n\nEines meiner Geräte, der magitastische Gizmonitor, sammelt und speichert dieses Wissen in riesigen Mengen! Aber ich verlor ihn! Als wir aus unserer Heimat Gnomeregan flohen, ließ ich ihn in einer Truhe in einer unserer Hütten vor der Stadt, und jetzt wimmelt es dort von Lepragnomen!\n\nBitte, {name}, findet meinen Gizmonitor wieder!", sourceObjective = "Bringt Bink ihren magitastischen Gizmonitor.", sourceObjectiveStatus = "unverified-source-field" }
quests[1881] = { id = 1881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Anastasia", description = "{name}, Anastasia Hirschbrunn hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Unterstadt und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.", sourceObjective = "Sprecht mit Anastasia Hirschbrunn.", sourceObjectiveStatus = "unverified-source-field" }
quests[1882] = { id = 1882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balnirs Bauernhof", description = "Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verderbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.\n\nDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen – Löwenmäulchen. Sammelt sie und kehrt zurück.", sourceObjective = "Bringt Balnirlöwenmäulchen zu Anastasia Hirschbrunn im Magierviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1883] = { id = 1883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Un'thuwa", description = "Un'thuwa, Stammesmagier in Sen'jin, spürt eine Störung in den magischen Strömen von Durotar und bittet um Unterstützung. Sprecht mit Un'thuwa und tut, was Ihr könnt, um ihm zu helfen.\n\nGelingt Euch das, werden Euch zu gegebener Zeit weitere Geheimnisse enthüllt.", sourceObjective = "Sprecht mit Un'thuwa.", sourceObjectiveStatus = "unverified-source-field" }
quests[1884] = { id = 1884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jujuhaufen", description = "Der Hexenmeister Zalazane von den Echoinseln hat den normalen Fluss der Magie in Durotar gestört. Das vollbringt er mit besudelten Fetischen, Jujuhaufen, die er auf der Echohauptinsel in seinen Hütten aufgeschichtet hat.\n\nDiese Haufen haben unser Ökosystem verdorben und Hexenmeistern und Höllenkreaturen, die in den dunklen Winkeln des Landes hausen, Macht gegeben.\n\nIhr müsst diese Jujuhaufen zerstören, {name}, bevor der Fluss der Magie für immer verändert ist.", sourceObjective = "Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1885] = { id = 1885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mennet Carkad", description = "{name}? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?\n\nSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.", sourceObjective = "Sprecht mit Mennet Carkad im Schurkenviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1886] = { id = 1886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, {name}, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", sourceObjective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1898] = { id = 1898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", sourceObjective = "Sprecht mit Andron Gant in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1899] = { id = 1899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", sourceObjective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1918] = { id = 1918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beschmutzte Element", description = "Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.\n\nEs ist nicht gerade allgemein bekannt, wer sich für solch einen Fund interessieren könnte; vielleicht hat ja Mastok Wutfauch im Splitterholzposten eine Idee.", sourceObjective = "Bringt die beschmutzte Wasserkugel zu Mastok Wutfauch im Splitterholzposten im Eschental.", progress = "Ja, was wollt Ihr?", completion = "Ihr findet eine eklige Kugel aus Wasser und beschließt, sie mir zu bringen? Wer bin ich denn, der Irdene Ring oder was?\n\nMoment mal, das bringt mich auf eine Idee... vielleicht braucht Ihr den Irdenen Ring dafür. Ich meine, wenn es dabei hilft, die Situation am See endgültig zu klären, dann bin ich absolut dafür.\n\nIhr wisst, wer der Irdene Ring ist, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[1919] = { id = 1919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Jennea", description = "Euer Wissen über das Handwerk wächst, {name}. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?\n\nWenn ja, sprecht mit Jennea Haubitz im Magiersanktum im Magierviertel von Sturmwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.", sourceObjective = "Sprecht in Sturmwind mit Jennea Haubitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1920] = { id = 1920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchungen im Blauen Eremiten", description = "Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.\n\nIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", sourceObjective = "Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Haubitz. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", sourceObjectiveStatus = "unverified-source-field" }
quests[1921] = { id = 1921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materialsammlung", description = "Ihr habt Euren Magierkollegen gut gedient, jetzt wird es Zeit, die Hexerrobe anzuziehen. Wynne Larson kann Eure Robe nähen, aber Ihr müsst ihr die erforderlichen Materialien bringen. \n\nEure Robe wird aus Leinen bestehen, das leicht zu beschaffen ist, aber Ihr müsst auch aufgeladene Rissedelsteine finden, die nur in der Silberbachmine vom Loch Modan zu finden sind, wo die Minenarbeiterliga der Zwerge sie in Kisten zurückgelassen hat.\n\nBeschafft das Leinen und die Edelsteine und bringt sie zu Wynne Larson in das Konfektionsgeschäft Larson im Magierviertel.", sourceObjective = "Bringt 10 Leinenstoff und 6 aufgeladene Rissedelsteine zu Wynne Larson in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1938] = { id = 1938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urs Abhandlung über Schattenmagie", description = "Vor langer Zeit studierten drei Magier in diesem Turm, bis einer den dunklen Künsten verfiel. Man bedrängte ihn, von dieser bösen Magie zu lassen, aber er konnte nicht widerstehen. Und so wurde er verbannt.\n\nDas neue Domizil des gefallenen Magiers ist der Turm von Ilgalar im Rotkammgebirge. Er hat ein mächtiges Buch dorthin mitgenommen -'Urs Abhandlung über Schattenmagie'.\n\nWir, die Magier von Sturmwind, möchten dieses Buch zurück. Begebt Euch in den Turm von Ilgalar, sucht den Folianten in seiner Bibliothek und bringt ihn mir.", sourceObjective = "Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1939] = { id = 1939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaubermeister Andromath", description = "Der Zaubermeister Andromath wünscht Euch zu sprechen, {name}. Er ist oben im Magiersanktum im Magierviertel von Sturmwind.\n\nEs wäre klug, mit ihm zu sprechen, denn Andromath ist einer der mächtigsten Magier, die nicht in Dalaran eingesperrt sind. Ein Rat von ihm ist in jedem Fall ein guter Rat.", sourceObjective = "Sprecht mit Zaubermeister Andromath.", sourceObjectiveStatus = "unverified-source-field" }
quests[1940] = { id = 1940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Spinnenseide", description = "Eure Treue ist unerschütterlich, {name}. Ich glaube, es ist an der Zeit, dass Ihr ein besseres Kleidungsstück bekommt, das einem geschickten Magier von Eurem Rang angemessener ist. Wenn Ihr die erforderlichen Materialien sammeln könnt, werde ich veranlassen, dass die Robe angefertigt wird.\n\nIhr müsst in den Dämmerwald und Aaskrabblerspinnen jagen. Extrahiert ihre Seide, aber nur die feinste und makelloseste. Wenn Ihr genug davon habt, bringt sie zu Wynne Larson ins Konfektionsgeschäft Larson hier im Magierviertel. Sie wird Eure Robe anfertigen.", sourceObjective = "Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1941] = { id = 1941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Managewirkte Robe" }
quests[1942] = { id = 1942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astralknotengewand" }
quests[1943] = { id = 1943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Deino", description = "Die Trollmagierin Deino bedarf Eurer Unterstützung, {name}. Sie residiert in Orgrimmar im Dunkeldornenlodge.", sourceObjective = "Sprecht mit Deino.", sourceObjectiveStatus = "unverified-source-field" }
quests[1944] = { id = 1944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser von Xavian", description = "Die legendäre Stadt Xavian liegt tief im östlichen Teil des Eschentals. Die Geschichten über ihr Wissen aus längst vergangener Zeit sind den Gebildeten wohl bekannt. Man sagt, die Wasser von Xavian bergen enorme magische Kräfte.\n\nBringt mir eine Probe dieses Wassers direkt von der Quelle.\n\nNehmt dieses Fläschchen und reist nach Xavian. Füllt Wasser am höchsten Wasserfall ab und kehrt zu mir zurück. Aber seid vorsichtig in der uralten Stadt - heute hausen Satyrn in den Ruinen, die gar nicht mögen, wenn sich Magier in ihre Angelegenheiten einmischen.", sourceObjective = "Bringt die Probe des Wassers von Xavian zu Deino in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
